        if (nbt.contains("InteractedWith")) {
            this.interactedWith = nbt.getBoolean("InteractedWith");
        }

        if (nbt.contains("clothes")) {
            validateClothes();
        }

        if (getVillagerBrain().getPersonality() == Personality.UNASSIGNED) {
            getVillagerBrain().randomize();
        }
    }

